+  const val = Math[key];
+  if (typeof val === 'number') {
+    MATH_CONSTANTS[key.toLowerCase()] = val;
+  } else if (typeof val === 'function') {
+    MATH_FUNCTIONS[key.toLowerCase()] = val;
+  }
